"""Full-frame H.264 capture through the pinned private Pixelflux 2.2.3 runtime."""
import struct
import threading

from .hevc_capture import runtime


MAX_PENDING_FRAMES = 120
FIRST_FRAME_TIMEOUT = 8


def _is_idr(payload):
    """Return whether an Annex-B access unit contains an IDR slice NAL."""
    position = 0
    while position < len(payload):
        start = payload.find(b"\\x00\\x00\\x01", position)
        prefix = 3
        if start < 0:
            start = payload.find(b"\\x00\\x00\\x00\\x01", position)
            prefix = 4
        if start < 0 or start + prefix >= len(payload):
            return False
        nal_type = payload[start + prefix] & 0x1F
        if nal_type == 5:
            return True
        position = start + prefix + 1
    return False


def packet(frame, width, height):
    """Adapt a Pixelflux 2.2.3 StripeFrame to Selkies' existing H.264 wire header."""
    if int(frame.data_type) != 1:
        raise RuntimeError(f"Unexpected Pixelflux frame type for H.264: {frame.data_type}")
    payload = bytes(frame)
    if not payload:
        raise RuntimeError("Pixelflux returned an empty H.264 access unit")
    frame_id = int(frame.frame_id) & 0xFFFF
    keyframe = _is_idr(payload)
    header = struct.pack("!BBHHHH", 1, int(keyframe), frame_id, 0, width, height)
    return header + payload, frame_id


class H264Capture:
    """H.264 adapter exposing the same live-control surface as HEVC and AV1."""

    def __init__(self):
        self.capture = runtime().ScreenCapture()
        self._settings = None
        self._stopped = False
        self._callback_error = None
        self._lock = threading.Lock()

    def start_capture(self, legacy, callback):
        module = runtime()
        settings = module.CaptureSettings()
        for name in (
            "capture_width", "capture_height", "capture_x", "capture_y", "capture_cursor",
            "target_fps", "scale", "auto_adjust_screen_capture_size", "use_cpu",
            "use_paint_over_quality", "paint_over_trigger_frames", "damage_block_threshold",
            "damage_block_duration", "watermark_location_enum",
        ):
            setattr(settings, name, getattr(legacy, name))

        watermark = legacy.watermark_path
        settings.watermark_path = watermark.decode("utf-8") if isinstance(watermark, bytes) else watermark
        for name in ("crf", "paintover_crf", "paintover_burst_frames", "streaming_mode"):
            setattr(settings, "video_" + name, getattr(legacy, "h264_" + name))

        settings.codec = "h264"
        settings.use_wayland = False
        settings.video_fullframe = True
        settings.video_fullcolor = bool(legacy.h264_fullcolor)
        settings.video_bit_depth = 8
        settings.omit_stripe_headers = False
        settings.encode_node_index = legacy.vaapi_render_node_index

        if not settings.use_cpu and "h264" not in module.hardware_encoders(settings.encode_node_index):
            raise RuntimeError("Selected GPU has no H.264 hardware encoder")

        first_keyframe = threading.Event()
        pending = []
        accepted = False
        have_keyframe = False
        self._stopped = False
        self._callback_error = None

        def deliver(frame):
            nonlocal accepted, have_keyframe
            with self._lock:
                if self._stopped or self._callback_error is not None:
                    return
                try:
                    data, frame_id = packet(frame, settings.capture_width, settings.capture_height)
                    keyframe = data[1] == 1
                    if not accepted:
                        if not have_keyframe and not keyframe:
                            return
                        have_keyframe = have_keyframe or keyframe
                        if len(pending) >= MAX_PENDING_FRAMES:
                            raise RuntimeError("H.264 startup frame queue overflow")
                        pending.append((data, frame_id))
                        if have_keyframe:
                            first_keyframe.set()
                        return
                    callback(data, frame_id)
                except Exception as exc:
                    self._callback_error = exc
                    first_keyframe.set()

        try:
            self.capture.start_capture(deliver, settings)
            self._settings = settings
            if not first_keyframe.wait(FIRST_FRAME_TIMEOUT):
                raise RuntimeError("H.264 encoder produced no IDR frame within 8 seconds")
            if self._callback_error is not None:
                raise RuntimeError(f"H.264 frame delivery failed: {self._callback_error}") from self._callback_error

            info = self.capture.stream_info() or {}
            if str(info.get("codec", "")).lower() != "h264":
                raise RuntimeError(f"Pixelflux did not start an H.264 session: {info}")
            if not settings.use_cpu and not info.get("hardware"):
                raise RuntimeError(
                    "H.264 hardware initialization failed: "
                    + str(info.get("encoder_reason", info))
                )

            with self._lock:
                if self._callback_error is not None:
                    raise RuntimeError(f"H.264 frame delivery failed: {self._callback_error}")
                for data, frame_id in pending:
                    callback(data, frame_id)
                pending.clear()
                accepted = True

            self.capture.request_idr_frame()
        except Exception:
            self._stopped = True
            self.capture.stop_capture()
            raise

    def update_framerate(self, fps):
        self.capture.update_framerate(float(fps))

    def update_paint_over(self, enabled):
        previous = self._settings.use_paint_over_quality
        self._settings.use_paint_over_quality = bool(enabled)
        try:
            self.capture.update_tunables(self._settings)
        except Exception:
            self._settings.use_paint_over_quality = previous
            raise

    def update_quality(self, legacy):
        for name in ("crf", "paintover_crf", "paintover_burst_frames", "streaming_mode"):
            setattr(self._settings, "video_" + name, getattr(legacy, "h264_" + name))
        self._settings.use_paint_over_quality = legacy.use_paint_over_quality
        self.capture.update_tunables(self._settings)

    def stop_capture(self):
        self._stopped = True
        self.capture.stop_capture()

    def request_idr_frame(self):
        self.capture.request_idr_frame()
